<script setup lang="ts">
import {ref,computed,onMounted,watch} from 'vue'
import {useRoute} from 'vue-router'
import Icon from '../components/Icon.vue'
import EventCard from '../components/EventCard.vue'
import {state,t,writeAccess,activeJob,runAnalysis,api,wp,notify,fmt} from '../state'
const route=useRoute(),query=ref(''),filter=ref('all'),category=ref(''),showAlerts=ref(route.query.alerts==='1'),savedOnly=ref(false),sort=ref('relevance')
const visible=computed(()=>{let e=state.events.filter(e=>(filter.value==='all'||e.sentiment===filter.value)&&(!category.value||e.category===category.value)&&(!savedOnly.value||state.saved.includes(e.id))&&(!query.value||JSON.stringify(e[state.locale]||e.en).toLowerCase().includes(query.value.toLowerCase())));return sort.value==='date'?e.sort((a,b)=>(b.published_at||b.created_at).localeCompare(a.published_at||a.created_at)):e.sort((a,b)=>b.relevance-a.relevance)})
async function read(){try{await api(wp('/alerts/read'),{method:'POST'});state.alerts=state.alerts.map(a=>({...a,read:true}))}catch(e:any){notify(e.message,true)}}
function open(id:string){state.selectedEvent=state.events.find(e=>e.id===id)}
watch(()=>route.query.alerts,v=>{showAlerts.value=v==='1'})
onMounted(()=>{if(route.query.event)open(String(route.query.event))})
</script>
<template><div class="page-heading"><div><span class="eyebrow">{{t('YOUR BUSINESS RADAR','РАДАР ВАШЕГО БИЗНЕСА')}}</span><h1>{{t('Signals, not noise.','Сигналы без шума.')}}</h1><p>{{t('Developments ranked by what they could change for your company.','События по значимости их возможного влияния на вашу компанию.')}}</p></div><div class="row gap-sm"><button class="btn secondary" @click="showAlerts=!showAlerts"><Icon name="Bell" :size="17"/>{{t('Notifications','Уведомления')}}<span class="count-pill">{{state.alerts.filter(a=>!a.read).length}}</span></button><button v-if="writeAccess" class="btn primary" :disabled="!!activeJob" @click="runAnalysis"><Icon name="RefreshCw" :size="16"/>{{t('Run monitoring','Мониторинг')}}</button></div></div>
<section v-if="showAlerts" class="card alerts-panel"><div class="card-heading"><h2>{{t('Your important updates','Важные обновления')}}</h2><button class="text-link" @click="read">{{t('Mark all as read','Прочитать все')}}</button></div><button v-for="a in state.alerts.slice(0,10)" :key="a.id" class="alert-row" :class="{unread:!a.read}" @click="open(a.event_id)"><span class="alert-dot" :class="{seen:a.read}"></span><div><strong>{{a[state.locale]}}</strong><span>{{fmt(a.created_at)}} · {{a.relevance}}% {{t('relevance','релевантность')}}</span></div><Icon name="ArrowUpRight" :size="17"/></button><div v-if="!state.alerts.length" class="empty compact-empty"><Icon name="Bell"/><p>{{t('No important updates yet. Your alert threshold is configurable in monitoring settings.','Важных обновлений пока нет. Порог уведомлений настраивается в мониторинге.')}}</p></div></section>
<div class="signals-toolbar"><div class="tabs filter-tabs"><button v-for="f in [{id:'all',en:'All signals',ru:'Все сигналы'},{id:'risk',en:'Risks',ru:'Риски'},{id:'opportunity',en:'Opportunities',ru:'Возможности'},{id:'mixed',en:'Mixed impact',ru:'Смешанное влияние'}]" :key="f.id" :class="{active:filter===f.id}" @click="filter=f.id">{{t(f.en,f.ru)}}<span>{{f.id==='all'?state.events.length:state.events.filter(e=>e.sentiment===f.id).length}}</span></button></div><button class="btn ghost small-btn" :class="{selected:savedOnly}" @click="savedOnly=!savedOnly"><Icon :name="savedOnly?'BookmarkCheck':'Bookmark'" :size="16"/>{{t('Saved','Избранное')}}</button></div>
<div class="search-filter-row"><label class="search-input"><Icon name="Search" :size="18"/><input v-model="query" :placeholder="t('Search signals, topics or business impacts…','Поиск событий, тем или влияния на бизнес…')" :aria-label="t('Search signals','Поиск сигналов')"></label><select v-model="category" :aria-label="t('Business driver','Фактор бизнеса')"><option value="">{{t('All business drivers','Все факторы бизнеса')}}</option><option v-for="c in ['macro','regulation','competition','technology','supply_chain','markets']" :key="c" :value="c">{{t({macro:'Macroeconomy',regulation:'Regulation',competition:'Competition',technology:'Technology',supply_chain:'Supply chain',markets:'Markets & FX'}[c],{macro:'Макроэкономика',regulation:'Регулирование',competition:'Конкуренция',technology:'Технологии',supply_chain:'Поставки',markets:'Рынки и валюта'}[c])}}</option></select><select v-model="sort" :aria-label="t('Sort signals','Сортировка сигналов')"><option value="relevance">{{t('Most relevant','По значимости')}}</option><option value="date">{{t('Most recent','По дате')}}</option></select></div><div class="results-line"><span>{{visible.length}} {{t('signals for your context','сигналов для вашего контекста')}}</span><span>{{t('Last 30 days','Последние 30 дней')}}</span></div><div v-if="visible.length" class="signals-grid"><EventCard v-for="e in visible" :key="e.id" :event="e"/></div><div v-else class="card empty"><span class="empty-icon"><Icon name="Radar" :size="30"/></span><h3>{{t('Nothing in this view yet.','В этом представлении пока пусто.')}}</h3><p>{{t('Try broader filters, add relevant sources or run monitoring for your decision role.','Измените фильтры, добавьте источники или запустите мониторинг для своей роли.')}}</p><button class="btn secondary" @click="query='';filter='all';category='';savedOnly=false">{{t('Clear filters','Сбросить фильтры')}}</button></div>
</template>
